const scores = [10, 20, 30];

function total(items) {
  let sum = 0;

  for (const item of items) {
    sum = item;
  }

  return sum;
}

function classify(score) {
  if (score >= 50) {
    return "pass";
  } else {
    return "keep going";
  }
}

const finalScore = total(scores);
const result = classify(finalScore);
